42	 *
43	 */
44	@Component( //
45			immediate = true, //
46			property = { //
47					"javax.portlet.name=" + GestioneFormsPortletKeys.GESTIONEFORMS, //
48					"mvc.command.name=" + GestioneFormsPortletKeys.SALVA_AGGIUNGI_ACTION_COMMAND }, //
49			service = { MVCActionCommand.class } //
50	)
51	public class SalvaModificaActionCommand extends BaseMVCActionCommand {
52	
53		public static final Log _log = LogFactoryUtil.getLog(SalvaModificaActionCommand.class);
54	
55		@Reference
56		private FormLocalService formLocalService;
57	
58		@Reference
59		private CounterLocalService counterLocalService;
60	
61		@Reference
62		private DefinizioneAllegatoLocalService definizioneAllegatoLocalService;
63	
64		@Reference
65		private GroupLocalService groupLocalService;
66	
67		@Reference
68		private GestioneFormsMiddlewareService gestioneFormsMiddlewareService;
69	
70		@Reference
71		private OrganizationUtility organizationUtility;
72	
73		@Reference
74		private SiteUtility siteUtility;
75	
76		@Reference
77		private AuditService auditService;
78	
79		@Override
80		protected void doProcessAction(ActionRequest actionRequest, ActionResponse actionResponse) throws Exception {
81	
82			ThemeDisplay themeDisplay = (ThemeDisplay) actionRequest.getAttribute(WebKeys.THEME_DISPLAY);
83	
84			UploadPortletRequest uploadPortletRequest = PortalUtil.getUploadPortletRequest(actionRequest);
85	
86			long idForm = ParamUtil.getLong(actionRequest, GestioneFormsPortletKeys.ID_FORM);
87			String codice = ParamUtil.getString(actionRequest, GestioneFormsPortletKeys.CODICE);
88			String nome = ParamUtil.getString(actionRequest, GestioneFormsPortletKeys.NOME);
89			boolean principale = ParamUtil.getBoolean(actionRequest, GestioneFormsPortletKeys.PRINCIPALE);
90			boolean pagamento = ParamUtil.getBoolean(actionRequest, GestioneFormsPortletKeys.PAGAMENTO);
91			String modelloForm = ParamUtil.getString(actionRequest, GestioneFormsPortletKeys.MODELLO_FORM);
92	
93			long indiceListaDefinizioneAllegati = ParamUtil.getLong(actionRequest, GestioneFormsPortletKeys.DIMENSIONE_LISTA_ALLEGATI);
94	
95			Form form = null;
96	
97			if (Validator.isNull(nome)) {
98				SessionErrors.add(actionRequest, GestioneFormsPortletKeys.SESSION_MESSAGE_ERRORE_SALVATAGGIO);
99				actionRequest.setAttribute(GestioneFormsPortletKeys.MODELLO_FORM, modelloForm);
100				actionResponse.getRenderParameters().setValue("jspPage", "/aggiungiModificaForm.jsp");
101				return;
102			}
103	
104			if (Validator.isNull(codice)) {
105				SessionErrors.add(actionRequest, GestioneFormsPortletKeys.SESSION_MESSAGE_ERRORE_SALVATAGGIO);
106				actionRequest.setAttribute(GestioneFormsPortletKeys.MODELLO_FORM, modelloForm);
107				actionResponse.getRenderParameters().setValue("jspPage", "/aggiungiModificaForm.jsp");
108				return;
109			}
110	
111			long groupId = 0;
112			long companyId = 0;
113			long organizationId = 0;
114	
115			if (Validator.isNotNull(idForm) && idForm > 0) {
116				form = formLocalService.getForm(idForm);
117	
118				if(Validator.isNotNull(form.getPrincipale()) && form.getPrincipale()) {
119					boolean checkAggiornamentoVersione = gestioneFormsMiddlewareService.checkUpdateStrutturaForm(modelloForm, form.getJson());
120	
121					if(checkAggiornamentoVersione) {
122						form.setVersione(form.getVersione() + 1);
123					}
124				}
125	
126				groupId = form.getGroupId();
127				companyId = form.getCompanyId();
128				organizationId = form.getOrganizationId();
129			}
130			else {
131				form = formLocalService.createForm(counterLocalService.increment());
132				form.setVersione(1);
133				groupId = themeDisplay.getScopeGroupId();
134				companyId = themeDisplay.getCompanyId();
135			}
136	
137			boolean isBackofficeMainSite = siteUtility.isBackofficeMainSite(themeDisplay);
138	
139			if (organizationId == 0 && !isBackofficeMainSite) {
140				Organization siteOrganization = organizationUtility.getSiteOrganization(themeDisplay.getSiteGroupId());
141				organizationId = siteOrganization.getOrganizationId();
142			}
143	
144			form.setCodice(codice);
145			form.setNome(nome);
146			form.setJson(modelloForm);
147			form.setPrincipale(principale);
148			form.setUserId(themeDisplay.getUserId());
149			form.setUserName(themeDisplay.getUser().getFullName());
150	
151			form.setOrganizationId(organizationId);
152			form.setGroupId(groupId);
153			form.setCompanyId(companyId);
154	
155			Form newForm = formLocalService.updateForm(form);
156			
157			List<Long> definizioniDaEliminare = new ArrayList<>();
158			definizioniDaEliminare.addAll(definizioneAllegatoLocalService.getListaDefinizioneAllegatoByFormId(idForm).stream()
159					.map(def -> def.getDefinizioneAllegatoId())
160					.collect(Collectors.toList()));
161			
162			// Recupero elenco allegati specificati nella creazione del form
163			try {
164				for (int i = 1; i <= indiceListaDefinizioneAllegati; i++) {
165					long definizioneAllegatoId = ParamUtil.getLong(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_ID + i);
166					String denominazione = ParamUtil.getString(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_DENOMINAZIONE + i);
167					String[] tipiFileAmmessi = ParamUtil.getParameterValues(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_FILE_AMMESSI + i);
168					String[] codiciTipologiaDocumento = ParamUtil.getParameterValues(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_CODICI_TIPOLOGIA + i);
169					String fileNameModello = ParamUtil.getString(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_FILENAME + i);
170					boolean obbligatorio = ParamUtil.getBoolean(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_OBBLIGATORIO + i);
171					boolean campoRipetibile = ParamUtil.getBoolean(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_CAMPO_RIPETIBILE + i);
172					boolean richiestaFirmaAllegato = ParamUtil.getBoolean(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_RICHIESTA_FIRMA + i);
173					boolean raggruppatoAllegato = ParamUtil.getBoolean(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_RAGGRUPPATO + i);
174					boolean istanzaAggiuntiva = ParamUtil.getBoolean(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_ISTANZA_AGGIUNTIVA + i);
175					long dimensioneMassimaFile = ParamUtil.getLong(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_DIMENSIONE_MASSIMA + i);
176					boolean modificato = ParamUtil.getBoolean(actionRequest, GestioneFormsPortletKeys.DEFINIZIONE_ALLEGATO_MODIFICATO + i);
177					List<TipoFirmaDigitale> tipiFirmaDigitale = TipoFirmaDigitale.parse(ParamUtil.getString(actionRequest, "tipiFirmaDigitale" + i));
178	
179					InputStream fileCaricato = uploadPortletRequest.getFileAsStream("fileInput" + i);
180					
181					definizioniDaEliminare.remove(definizioneAllegatoId);
182	
183					if (modificato) {
184						if (Validator.isNull(denominazione)) {
185							SessionErrors.add(actionRequest, GestioneFormsPortletKeys.SESSION_MESSAGE_ERRORE_SALVATAGGIO);
186							actionRequest.setAttribute(GestioneFormsPortletKeys.MODELLO_FORM, modelloForm);
187							actionResponse.getRenderParameters().setValue("jspPage", "/aggiungiModificaForm.jsp");
188							return;
189						}
190		
191						if (Validator.isNull(tipiFileAmmessi)) {
192							SessionErrors.add(actionRequest, GestioneFormsPortletKeys.SESSION_MESSAGE_ERRORE_SALVATAGGIO);
193							actionRequest.setAttribute(GestioneFormsPortletKeys.MODELLO_FORM, modelloForm);
194							actionResponse.getRenderParameters().setValue("jspPage", "/aggiungiModificaForm.jsp");
195							return;
196						}
197	
198						if (istanzaAggiuntiva && definizioneAllegatoLocalService.existsAltroAllegatoIstanzaAggiuntiva(form.getFormId(), definizioneAllegatoId)) {
199							SessionErrors.add(actionRequest, GestioneFormsPortletKeys.SESSION_MESSAGE_ERRORE_ISTANZA_AGGIUNTIVA_DUPLICATA);
200							actionRequest.setAttribute(GestioneFormsPortletKeys.MODELLO_FORM, modelloForm);
201							actionResponse.getRenderParameters().setValue("mvcRenderCommandName", GestioneFormsPortletKeys.DETTAGLIO_NUOVO_RENDER_COMMAND);
202							return;
203						}
204	
205						gestioneFormsMiddlewareService.salvaAllegatoTemplate(definizioneAllegatoId, denominazione, tipiFileAmmessi, codiciTipologiaDocumento, fileNameModello, obbligatorio, fileCaricato,
206								form.getFormId(), themeDisplay.getUserId(), themeDisplay.getSiteGroupId(), dimensioneMassimaFile, campoRipetibile, richiestaFirmaAllegato, tipiFirmaDigitale, raggruppatoAllegato, istanzaAggiuntiva);
207					}
208				}
209			}
210			catch (Exception e) {
211				_log.error("doProcessAction :: " + e.getMessage(), e);
212	
213				auditService.saveErrorLog(actionRequest, e.getMessage());
214	
215				// rollback in caso di generazione nuovo form
216				if (Validator.isNull(idForm)) {
217					formLocalService.deleteForm(newForm);
218				}
219	
220	
221				SessionErrors.add(actionRequest, GestioneFormsPortletKeys.SESSION_MESSAGE_ERRORE_SALVATAGGIO_ALLEGATI);
222				actionRequest.setAttribute(GestioneFormsPortletKeys.MODELLO_FORM, modelloForm);
223				actionResponse.getRenderParameters().setValue("mvcRenderCommandName", GestioneFormsPortletKeys.DETTAGLIO_NUOVO_RENDER_COMMAND);
224				return;
225			}
226	
227			// Controllo su eventuali rimozioni degli allegati
228			gestioneFormsMiddlewareService.eliminaAllegati(definizioniDaEliminare);
229	
230			SessionMessages.add(actionRequest, GestioneFormsPortletKeys.SESSION_MESSAGE_ESEGUITO_CORRETTAMENTE);
231		}
232	
233	}
