266		public boolean checkUpdateStrutturaForm(String jsonNew, String jsonOld) {
267	
268			boolean differenzeTrovate = false;
269	
270			if (Validator.isNotNull(jsonNew) && Validator.isNotNull(jsonOld)) {
271	
272				List<String> labelsOldForm = getLabelKeyFieldsForm(jsonOld);
273				List<String> labelsFormNew = getLabelKeyFieldsForm(jsonNew);
274	
275				Set<Entry<String, JsonElement>> schemaFormNew = getSchemaFieldsForm(jsonNew, labelsFormNew);
276				Set<Entry<String, JsonElement>> schemaFormOld = getSchemaFieldsForm(jsonOld, labelsOldForm);
277	
278				Set<Entry<String, JsonElement>> fieldEliminati = schemaFormOld.stream()
279						.filter(field -> !schemaFormNew.contains(field)).collect(Collectors.toSet());
280	
281				Set<Entry<String, JsonElement>> fieldAggiunti = schemaFormNew.stream()
282						.filter(field -> !schemaFormOld.contains(field)).collect(Collectors.toSet());
283	
284				if (!fieldEliminati.isEmpty() || !fieldAggiunti.isEmpty()) {
285					differenzeTrovate = true;
286				}
287	
288			}
289	
290			return differenzeTrovate;
291		}
