293		private List<String> getLabelKeyFieldsForm(String json) {
294			Set<Entry<String, JsonElement>> optionsFields = null;
295			List<String> labelKeys = new ArrayList<String>();
296	
297			if (Validator.isNotNull(json)) {
298				JsonObject jsonObject = new JsonParser().parse(json).getAsJsonObject();
299	
300				if (jsonObject.has("options") && !jsonObject.get("options").isJsonNull()) {
301					JsonObject options = jsonObject.get("options").getAsJsonObject();
302	
303					if (options.has("fields") && !options.get("fields").isJsonNull()) {
304						JsonObject fieldsObj = options.get("fields").getAsJsonObject();
305						optionsFields = fieldsObj.entrySet();
306					}
307				}
308			}
309	
310			if (Validator.isNotNull(optionsFields) && !optionsFields.isEmpty()) {
311				for (Entry<String, JsonElement> field : optionsFields) {
312					if (Validator.isNotNull(field)) {
313						JsonElement fieldJsonElement = field.getValue();
314	
315						if (Validator.isNotNull(fieldJsonElement)) {
316							JsonObject fieldObj = fieldJsonElement.getAsJsonObject();
317	
318							if (Validator.isNotNull(fieldObj)) {
319								if (fieldObj.has("type") && !fieldObj.get("type").isJsonNull()) {
320									String type = fieldObj.get("type").getAsString();
321	
322									if (Validator.isNotNull(type) && type.equalsIgnoreCase("label")) {
323										labelKeys.add(field.getKey());
324									}
325								}
326							}
327						}
328					}
329				}
330			}
331	
332			return labelKeys;
333		}
