335		private Set<Entry<String, JsonElement>> getSchemaFieldsForm(String json, List<String> labelsToRemove) {
336			Set<Entry<String, JsonElement>> schemaFields = null;
337			Set<Entry<String, JsonElement>> schemaFieldsFiltered = new HashSet<Entry<String, JsonElement>>();
338	
339			if (Validator.isNotNull(json)) {
340				JsonObject jsonObject = new JsonParser().parse(json).getAsJsonObject();
341	
342				if (jsonObject.has("schema") && !jsonObject.get("schema").isJsonNull()) {
343					JsonObject schema = jsonObject.get("schema").getAsJsonObject();
344	
345					if (schema.has("properties") && !schema.get("properties").isJsonNull()) {
346						JsonObject propertiesObj = schema.get("properties").getAsJsonObject();
347						schemaFields = propertiesObj.entrySet();
348					}
349				}
350	
351				if (Validator.isNotNull(schemaFields) && labelsToRemove != null && !labelsToRemove.isEmpty()) {
352					for (Entry<String, JsonElement> field : schemaFields) {
353						if (Validator.isNotNull(field)) {
354							if (!labelsToRemove.contains(field.getKey())) {
355								schemaFieldsFiltered.add(field);
356							}
357						}
358					}
359				} else {
360					schemaFieldsFiltered = schemaFields;
361				}
362			}
363	
364			return schemaFieldsFiltered;
365		}
