package it.servizidigitali.gestioneforms.frontend.service;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.liferay.counter.kernel.service.CounterLocalService;
import com.liferay.petra.string.StringPool;
import com.liferay.portal.kernel.exception.PortalException;
import com.liferay.portal.kernel.language.LanguageUtil;
import com.liferay.portal.kernel.model.Company;
import com.liferay.portal.kernel.model.Group;
import com.liferay.portal.kernel.model.GroupConstants;
import com.liferay.portal.kernel.model.Organization;
import com.liferay.portal.kernel.model.User;
import com.liferay.portal.kernel.service.CompanyLocalService;
import com.liferay.portal.kernel.service.GroupLocalService;
import com.liferay.portal.kernel.service.UserLocalService;
import com.liferay.portal.kernel.theme.ThemeDisplay;
import com.liferay.portal.kernel.util.PropsKeys;
import com.liferay.portal.kernel.util.PropsUtil;
import com.liferay.portal.kernel.util.ResourceBundleUtil;
import com.liferay.portal.kernel.util.Validator;

import java.io.InputStream;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.HashSet;
import java.util.List;
import java.util.Map.Entry;
import java.util.ResourceBundle;
import java.util.Set;
import java.util.stream.Collectors;

import javax.portlet.PortletRequest;

import it.servizidigitali.common.utility.enumeration.TipoFirmaDigitale;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import it.servizidigitali.common.utility.OrganizationUtility;
import it.servizidigitali.common.utility.SiteUtility;
import it.servizidigitali.gestioneforms.model.DefinizioneAllegato;
import it.servizidigitali.gestioneforms.model.Form;
import it.servizidigitali.gestioneforms.service.DefinizioneAllegatoLocalService;
import it.servizidigitali.gestioneforms.service.FormLocalService;

@Component(name = "gestioneFormsMiddlewareService", immediate = true, service = GestioneFormsMiddlewareService.class)
public class GestioneFormsMiddlewareService {

	@Reference
	private TemplateAllegatoFileService templateAllegatoFileService;

	@Reference
	private DefinizioneAllegatoLocalService definizioneAllegatoLocalService;

	@Reference
	private CounterLocalService counterLocalService;

	@Reference
	private CompanyLocalService companyLocalService;

	@Reference
	private GroupLocalService groupLocalService;

	@Reference
	private UserLocalService userLocalService;

	@Reference
	private FormLocalService formLocalService;

	@Reference
	private OrganizationUtility organizationUtility;

	@Reference
	private SiteUtility siteUtility;

	/**
	 *
	 * @param nome
	 * @param dataInserimentoDa
	 * @param dataInserimentoA
	 * @param inizio
	 * @param fine
	 * @param orderByCol
	 * @param orderByType
	 * @param themeDisplay
	 * @return
	 * @throws PortalException
	 */
	public List<Form> searchForms(String nome, Date dataInserimentoDa, Date dataInserimentoA, int inizio, int fine,
			String orderByCol, String orderByType, ThemeDisplay themeDisplay) throws PortalException {

		boolean isBackofficeMainSite = siteUtility.isBackofficeMainSite(themeDisplay);
		long groupId = themeDisplay.getScopeGroupId();
		long companyId = themeDisplay.getCompanyId();

		List<Long> companyIds = new ArrayList<Long>();
		companyIds.add(companyId);

		Company defaultCompany = companyLocalService.getCompanyByMx(PropsUtil.get(PropsKeys.COMPANY_DEFAULT_WEB_ID));
		companyIds.add(defaultCompany.getCompanyId());

		List<Long> groupIds = new ArrayList<Long>();
		groupIds.add(groupId);
		Group mainSiteGroup = groupLocalService.getGroup(defaultCompany.getCompanyId(), GroupConstants.GUEST);
		groupIds.add(mainSiteGroup.getGroupId());

		if (isBackofficeMainSite) {
			groupIds = null;
			companyIds = null;
		}

		List<Form> forms = formLocalService.search(nome, dataInserimentoDa, dataInserimentoA, inizio, fine, groupIds,
				companyIds, orderByCol, orderByType);
		elaborateForms(forms);
		return forms;
	}

	/**
	 *
	 * @param nome
	 * @param dataInserimentoDa
	 * @param dataInserimentoA
	 * @param themeDisplay
	 * @return
	 * @throws PortalException
	 */
	public long count(String nome, Date dataInserimentoDa, Date dataInserimentoA, ThemeDisplay themeDisplay)
			throws PortalException {

		boolean isBackofficeMainSite = siteUtility.isBackofficeMainSite(themeDisplay);
		long groupId = themeDisplay.getScopeGroupId();
		long companyId = themeDisplay.getCompanyId();

		List<Long> companyIds = new ArrayList<Long>();
		companyIds.add(companyId);

		Company defaultCompany = companyLocalService.getCompanyByMx(PropsUtil.get(PropsKeys.COMPANY_DEFAULT_WEB_ID));
		companyIds.add(defaultCompany.getCompanyId());

		List<Long> groupIds = new ArrayList<Long>();
		groupIds.add(groupId);
		Group mainSiteGroup = groupLocalService.getGroup(defaultCompany.getCompanyId(), GroupConstants.GUEST);
		groupIds.add(mainSiteGroup.getGroupId());

		if (isBackofficeMainSite) {
			groupIds = null;
			companyIds = null;
		}

		long totale = formLocalService.count(nome, dataInserimentoDa, dataInserimentoA, groupIds, companyIds);

		return totale;
	}

	/**
	 *
	 * @param forms
	 * @return
	 * @throws PortalException
	 */
	private void elaborateForms(List<Form> forms) throws PortalException {
		if (forms != null) {
			for (Form form : forms) {
				Organization siteOrganization = organizationUtility.getSiteOrganization(form.getGroupId());
				if (siteOrganization != null) {
					form.setNomeEnte(siteOrganization.getName());
				}
			}
		}
	}

	public long salvaAllegatoTemplate(long definizioneAllegatoId, String denominazione, String[] tipiFileAmmessi,
									  String[] codiciTipologiaDocumento, String fileNameModello, boolean obbligatorio, InputStream fileCaricato,
									  long formId, long userId, long groupId, long dimensioneMassimaFile, boolean campoRipetibile, boolean richiestFirmaAllegato, List<TipoFirmaDigitale> tipiFirmaDigitale, boolean almenoUnoObbligatorio, boolean istanzaAggiuntiva) throws Exception {

		DefinizioneAllegato allegato = definizioneAllegatoLocalService.createDefinizioneAllegato(0);
		long idAllegatoCaricato = 0;

		if (definizioneAllegatoId > 0) {
			allegato = definizioneAllegatoLocalService.getDefinizioneAllegato(definizioneAllegatoId);
		} else {
			allegato.setDefinizioneAllegatoId(counterLocalService.increment());
		}

		if (Validator.isNotNull(fileNameModello)) {
			String nomefile = fileNameModello.substring(0, fileNameModello.lastIndexOf("."));
			String estensione = fileNameModello.substring(fileNameModello.lastIndexOf("."));
			fileNameModello = nomefile + "_" + String.valueOf(allegato.getDefinizioneAllegatoId()) + "_"
					+ nowToString() + estensione;
		}

		idAllegatoCaricato = templateAllegatoFileService.saveTemplateAllegato(fileNameModello, denominazione, null,
				formId, fileCaricato, null, userId, groupId);

		if (Validator.isNotNull(denominazione)) {
			allegato.setDenominazione(denominazione);
		}

		if (Validator.isNotNull(tipiFileAmmessi)) {
			allegato.setTipiFileAmmessi(String.join(",", tipiFileAmmessi));
		}

		if (Validator.isNotNull(codiciTipologiaDocumento)) {
			allegato.setCodiciTipologiaDocumento(String.join(",", codiciTipologiaDocumento));
		}

		allegato.setFilenameModello(fileNameModello);

		allegato.setObbligatorio(obbligatorio);
		allegato.setRipetibile(campoRipetibile);
		allegato.setRichiestaFirma(richiestFirmaAllegato);
		allegato.setAlmenoUnoObbligatorio(almenoUnoObbligatorio);
		allegato.setIstanzaAggiuntiva(istanzaAggiuntiva);

		String formatiFirmaDigitale;
		if (richiestFirmaAllegato) {
			formatiFirmaDigitale = TipoFirmaDigitale.stringify(tipiFirmaDigitale);
		} else {
			formatiFirmaDigitale = StringPool.BLANK;
		}
		allegato.setFormatiFirmaDigitale(formatiFirmaDigitale);

		allegato.setFormId(formId);

		if (idAllegatoCaricato > 0) {
			allegato.setFileEntryId(idAllegatoCaricato);
		}

		User user = userLocalService.getUser(userId);

		allegato.setUserId(userId);
		allegato.setUserName(user.getFullName());

		allegato.setGroupId(groupId);
		allegato.setOrganizationId(groupLocalService.getGroup(groupId).getOrganizationId());
		allegato.setDimensioneMassimaFile(dimensioneMassimaFile);

		definizioneAllegatoLocalService.updateDefinizioneAllegato(allegato);

		return allegato.getDefinizioneAllegatoId();
	}

	public static String nowToString() {
		SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd-HH-mm-ss");
		return sdf.format(new Date());
	}

	/**
	 *
	 * @param ids
	 * @throws PortalException
	 */
	public void eliminaAllegati(List<Long> allegatiDaEliminare) throws PortalException {

		for (Long id : allegatiDaEliminare) {
			DefinizioneAllegato definizioneAllegato = definizioneAllegatoLocalService.getDefinizioneAllegato(id);
			if (definizioneAllegato != null && definizioneAllegato.getFileEntryId() != 0) {
				templateAllegatoFileService.deleteTemplateAllegato(definizioneAllegato.getFileEntryId());
			}
		}
		definizioneAllegatoLocalService.deleteAllegati(allegatiDaEliminare);
	}

	public boolean checkUpdateStrutturaForm(String jsonNew, String jsonOld) {

		boolean differenzeTrovate = false;

		if (Validator.isNotNull(jsonNew) && Validator.isNotNull(jsonOld)) {

			List<String> labelsOldForm = getLabelKeyFieldsForm(jsonOld);
			List<String> labelsFormNew = getLabelKeyFieldsForm(jsonNew);

			Set<Entry<String, JsonElement>> schemaFormNew = getSchemaFieldsForm(jsonNew, labelsFormNew);
			Set<Entry<String, JsonElement>> schemaFormOld = getSchemaFieldsForm(jsonOld, labelsOldForm);

			Set<Entry<String, JsonElement>> fieldEliminati = schemaFormOld.stream()
					.filter(field -> !schemaFormNew.contains(field)).collect(Collectors.toSet());

			Set<Entry<String, JsonElement>> fieldAggiunti = schemaFormNew.stream()
					.filter(field -> !schemaFormOld.contains(field)).collect(Collectors.toSet());

			if (!fieldEliminati.isEmpty() || !fieldAggiunti.isEmpty()) {
				differenzeTrovate = true;
			}

		}

		return differenzeTrovate;
	}

	private List<String> getLabelKeyFieldsForm(String json) {
		Set<Entry<String, JsonElement>> optionsFields = null;
		List<String> labelKeys = new ArrayList<String>();

		if (Validator.isNotNull(json)) {
			JsonObject jsonObject = new JsonParser().parse(json).getAsJsonObject();

			if (jsonObject.has("options") && !jsonObject.get("options").isJsonNull()) {
				JsonObject options = jsonObject.get("options").getAsJsonObject();

				if (options.has("fields") && !options.get("fields").isJsonNull()) {
					JsonObject fieldsObj = options.get("fields").getAsJsonObject();
					optionsFields = fieldsObj.entrySet();
				}
			}
		}

		if (Validator.isNotNull(optionsFields) && !optionsFields.isEmpty()) {
			for (Entry<String, JsonElement> field : optionsFields) {
				if (Validator.isNotNull(field)) {
					JsonElement fieldJsonElement = field.getValue();

					if (Validator.isNotNull(fieldJsonElement)) {
						JsonObject fieldObj = fieldJsonElement.getAsJsonObject();

						if (Validator.isNotNull(fieldObj)) {
							if (fieldObj.has("type") && !fieldObj.get("type").isJsonNull()) {
								String type = fieldObj.get("type").getAsString();

								if (Validator.isNotNull(type) && type.equalsIgnoreCase("label")) {
									labelKeys.add(field.getKey());
								}
							}
						}
					}
				}
			}
		}

		return labelKeys;
	}

	private Set<Entry<String, JsonElement>> getSchemaFieldsForm(String json, List<String> labelsToRemove) {
		Set<Entry<String, JsonElement>> schemaFields = null;
		Set<Entry<String, JsonElement>> schemaFieldsFiltered = new HashSet<Entry<String, JsonElement>>();

		if (Validator.isNotNull(json)) {
			JsonObject jsonObject = new JsonParser().parse(json).getAsJsonObject();

			if (jsonObject.has("schema") && !jsonObject.get("schema").isJsonNull()) {
				JsonObject schema = jsonObject.get("schema").getAsJsonObject();

				if (schema.has("properties") && !schema.get("properties").isJsonNull()) {
					JsonObject propertiesObj = schema.get("properties").getAsJsonObject();
					schemaFields = propertiesObj.entrySet();
				}
			}

			if (Validator.isNotNull(schemaFields) && labelsToRemove != null && !labelsToRemove.isEmpty()) {
				for (Entry<String, JsonElement> field : schemaFields) {
					if (Validator.isNotNull(field)) {
						if (!labelsToRemove.contains(field.getKey())) {
							schemaFieldsFiltered.add(field);
						}
					}
				}
			} else {
				schemaFieldsFiltered = schemaFields;
			}
		}

		return schemaFieldsFiltered;
	}

	public String getLabel(PortletRequest request, String key, Object... args) {
		ResourceBundle bundle = ResourceBundleUtil.getBundle(request.getLocale(), getClass());
		String format = bundle.getString(key);
		String message = LanguageUtil.format(request.getLocale(), format, args);
		return message;
	}
}

