package it.servizidigitali.presentatoreforms.common.service;

import com.liferay.counter.kernel.service.CounterLocalService;
import com.liferay.document.library.kernel.service.DLAppService;
import com.liferay.portal.kernel.exception.PortalException;
import com.liferay.portal.kernel.log.Log;
import com.liferay.portal.kernel.log.LogFactoryUtil;
import com.liferay.portal.kernel.repository.model.FileEntry;
import com.liferay.portal.kernel.util.MimeTypesUtil;
import com.liferay.portal.kernel.util.Validator;

import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.util.List;
import java.util.stream.Collectors;

import it.servizidigitali.common.fdr.dto.VerificaFirmaOptions;
import it.servizidigitali.common.fdr.exception.VerificaFirmaException;
import it.servizidigitali.common.fdr.service.FirmaRemotaService;
import it.servizidigitali.common.utility.enumeration.Contesto;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import it.servizidigitali.common.utility.enumeration.TipoFirmaDigitale;
import it.servizidigitali.file.utility.exception.FileServiceException;
import it.servizidigitali.file.utility.factory.FileServiceFactory;
import it.servizidigitali.file.utility.model.File;
import it.servizidigitali.file.utility.service.FileService;
import it.servizidigitali.gestioneforms.model.DefinizioneAllegato;
import it.servizidigitali.gestioneforms.service.DefinizioneAllegatoLocalService;
import it.servizidigitali.gestioneservizi.model.Servizio;
import it.servizidigitali.presentatoreforms.common.exception.PDFSignatureException;
import it.servizidigitali.presentatoreforms.common.exception.SalvataggioAllegatoException;
import it.servizidigitali.presentatoreforms.common.model.DatiFileAllegato;
import it.servizidigitali.scrivaniaoperatore.model.AllegatoRichiesta;
import it.servizidigitali.scrivaniaoperatore.service.AllegatoRichiestaLocalService;

@Component(name = "allegatiRichiestaService", immediate = true, service = AllegatoRichiestaService.class)
public class AllegatoRichiestaService {

	private static final Log log = LogFactoryUtil.getLog(AllegatoRichiestaService.class.getName());

	@Reference
	private FileServiceFactory fileServiceFactory;

	@Reference
	private AllegatoRichiestaLocalService allegatoRichiestaLocalService;

	@Reference
	private DefinizioneAllegatoLocalService definizioneAllegatoLocalService;

	@Reference
	private CounterLocalService counterLocalService;

	@Reference
	private DLAppService dlAppService;

	@Reference
	private FirmaRemotaService firmaRemotaService;

	/**
	 *
	 * @param allegato
	 * @param nomeFile
	 * @param titolo
	 * @param servizio
	 * @param richiestaId
	 * @param definizioneAllegatoId
	 * @param istanzaFormId
	 * @param userName
	 * @param userId
	 * @param groupId
	 * @param companyId
	 * @return allegatoRichiestaId
	 * @throws Exception
	 */
	public long salvaAllegatoRichiesta(byte[] allegato, String nomeFile, String titolo, Servizio servizio, long richiestaId, Long definizioneAllegatoId, long istanzaFormId, String userName,
			long userId, long groupId, long companyId) throws Exception {
		long allegatoRichiestaId = 0;
		String idDocumentale = null;
		try {
			if (Validator.isNotNull(allegato)) {
				InputStream stream = new ByteArrayInputStream(allegato);
				String descrizione = null;
				if (definizioneAllegatoId != null && !definizioneAllegatoId.equals(0L)) {
					try {
						DefinizioneAllegato definizioneAllegato = definizioneAllegatoLocalService.getDefinizioneAllegato(definizioneAllegatoId);
						descrizione = "Allegato '" + definizioneAllegato.getDenominazione() + "'";
					}
					catch (PortalException e) {
						log.error("salvaAllegatiRichiesta :: " + e.getMessage(), e);
					}
				}

				String mimeType = MimeTypesUtil.getContentType(stream, nomeFile);
				File savedFile = fileServiceFactory.getActiveFileService().saveRequestFile(nomeFile, titolo, descrizione, servizio.getCodice(), richiestaId, stream, mimeType, userId, groupId);
				if(Validator.isNotNull(savedFile) && Validator.isNotNull(savedFile.getId())) {
					idDocumentale = savedFile.getId();
					allegatoRichiestaId = creaAllegatoRichiesta(savedFile.getId(), savedFile.getNome(), titolo, descrizione, servizio.getNome(), richiestaId, definizioneAllegatoId, istanzaFormId, false,
							true, userId, userName, groupId, companyId);
				}
			}
		}
		catch (Exception e) {
			log.error("Errore durante il caricamento del file : " + e.getMessage(), e);
			//Se qualcosa  andato storto durante la creazione del file, elimino il file dal documentale
			if (Validator.isNotNull(idDocumentale)) {
				fileServiceFactory.getActiveFileService().deleteRequestFile(idDocumentale, groupId);
				throw new SalvataggioAllegatoException("Caricamento dell'allegato " + titolo + " non eseguito correttamente", e);
			}
			throw new SalvataggioAllegatoException("Caricamento dell'allegato " + titolo + " non eseguito correttamente sul sistema documentale", e);
		}
		return allegatoRichiestaId;

	}

	/**
	 *
	 * @param idDocumentale
	 * @param nomeFile
	 * @param titolo
	 * @param descrizione
	 * @param nomeServizio
	 * @param richiestaId
	 * @param definizioneAllegatoId
	 * @param istanzaFormId
	 * @param principale
	 * @param visibile
	 * @param userId
	 * @param userName
	 * @param groupId
	 * @param companyId
	 * @return allegatoRichiestaId
	 */
	public long creaAllegatoRichiesta(String idDocumentale, String nomeFile, String titolo, String descrizione, String nomeServizio, long richiestaId, Long definizioneAllegatoId, long istanzaFormId,
			boolean principale, boolean visibile, long userId, String userName, long groupId, long companyId) {
		AllegatoRichiesta allegatoRichiesta = allegatoRichiestaLocalService.createAllegatoRichiesta(counterLocalService.increment());

		if (Validator.isNotNull(idDocumentale)) {
			allegatoRichiesta.setGroupId(groupId);
			allegatoRichiesta.setCompanyId(companyId);
			allegatoRichiesta.setUserId(userId);
			allegatoRichiesta.setUserName(userName);
			allegatoRichiesta.setRichiestaId(richiestaId);
			allegatoRichiesta.setIdDocumentale(idDocumentale);
			allegatoRichiesta.setDefinizioneAllegatoId(definizioneAllegatoId);
			allegatoRichiesta.setPrincipale(principale);
			allegatoRichiesta.setNome(nomeFile);
			allegatoRichiesta.setTitolo(titolo);
			allegatoRichiesta.setDescrizione(descrizione);
			allegatoRichiesta.setVisibile(visibile);
			allegatoRichiesta.setIstanzaFormId(istanzaFormId);

			allegatoRichiesta = allegatoRichiestaLocalService.updateAllegatoRichiesta(allegatoRichiesta);
		}

		return allegatoRichiesta.getAllegatoRichiestaId();
	}

	/**
	 *
	 * @param allegato
	 * @param servizio
	 * @param richiestaId
	 * @param istanzaFormId
	 * @param userName
	 * @param userId
	 * @param groupId
	 * @param companyId
	 * @return allegatoRichiestaId
	 * @throws Exception
	 */
	public long salvaDocumentoPrincipaleRichiesta(byte[] allegato, Servizio servizio, long richiestaId, long istanzaFormId, String userName, long userId, long groupId, long companyId)
			throws Exception {
		long allegatoRichiestaId = 0;
		String idDocumentale = null;
		try {
			if (Validator.isNotNull(allegato)) {
				InputStream stream = new ByteArrayInputStream(allegato);
				String nomeFile = "richiesta-" + richiestaId + ".pdf";
				String descrizione = "Richiesta servizio '" + servizio.getNome() + "' - ID: " + richiestaId;
				String mimeType = MimeTypesUtil.getContentType(stream, nomeFile);
				File savedFile = fileServiceFactory.getActiveFileService().saveRequestFile(nomeFile, nomeFile, descrizione, servizio.getCodice(), richiestaId, stream, mimeType, userId, groupId);


				if (Validator.isNotNull(savedFile != null && savedFile.getId() != null)) {
					idDocumentale = savedFile.getId();
					allegatoRichiestaId = creaAllegatoRichiesta(savedFile.getId(), savedFile.getNome(), nomeFile, descrizione, servizio.getNome(), richiestaId, null, istanzaFormId, true, true, userId,
							userName, groupId, companyId);
					//Rimosso per gestire la casistica di rollback sul documentale
					//return allegatoRichiestaId;
				}
			}
		}
		catch (Exception e) {
			log.error("Errore durante il caricamento del file firmato : " + e.getMessage(), e);
			//Se qualcosa � andato storto durante la creazione del file, elimino il file dal documentale
			if (Validator.isNotNull(idDocumentale)) {
				fileServiceFactory.getActiveFileService().deleteRequestFile(idDocumentale, groupId);
				throw new SalvataggioAllegatoException("Caricamento del documento principale non eseguito correttamente", e);
			}
			throw new SalvataggioAllegatoException("Caricamento del documento principale sul sistema documentale non eseguito correttamente", e);
		}
		return allegatoRichiestaId;
	}

	/**
	 *
	 * @param certificato
	 * @param servizio
	 * @param richiestaId
	 * @param istanzaFormId
	 * @param userName
	 * @param userId
	 * @param groupId
	 * @param companyId
	 * @return idDocumentale
	 * @throws Exception
	 */
	public String salvaCertificato(byte[] certificato, Servizio servizio, long richiestaId, long istanzaFormId, String userName, long userId, long groupId, long companyId) throws Exception {

		String idDocumentale = null;

		try {

			if (Validator.isNotNull(certificato)) {
				InputStream is = new ByteArrayInputStream(certificato);
				String nomeFile = "richiesta-" + richiestaId + ".pdf";
				String descrizione = "Richiesta servizio '" + servizio.getNome() + "' - ID: " + richiestaId;

				if (Validator.isNotNull(is)) {
					String mimeType = MimeTypesUtil.getContentType(is, nomeFile);
					File savedFile = fileServiceFactory.getActiveFileService().saveRequestFile(nomeFile, nomeFile, descrizione, servizio.getCodice(), richiestaId, is, mimeType, userId, groupId);

					if (Validator.isNotNull(savedFile != null && savedFile.getId() != null)) {
						creaAllegatoRichiesta(savedFile.getId(), savedFile.getNome(), savedFile.getNome(), descrizione, servizio.getNome(), richiestaId, null, istanzaFormId, true, true, userId,
								userName, groupId, companyId);

						idDocumentale = savedFile.getId();
					}
				}

			}

		}
		catch (Exception e) {
			log.error(e.getMessage(), e);
			throw e;
		}

		return idDocumentale;
	}

	/**
	 *
	 * @param idDocumentale
	 * @param groupId
	 * @return
	 * @throws Exception
	 */
	public byte[] getCertificato(String idDocumentale, long groupId) throws Exception {
		byte[] certificato = null;

		try {
			certificato = fileServiceFactory.getActiveFileService().getRequestFileContent(idDocumentale, groupId).readAllBytes();
		}
		catch (Exception e) {
			log.error(e.getMessage(), e);
			throw e;
		}

		return certificato;
	}

	/**
	 *
	 * @param definizioneAllegatoId
	 * @return
	 */
	public DatiFileAllegato getModelloAllegato(long definizioneAllegatoId) {
		DatiFileAllegato modello = null;
		DefinizioneAllegato allegato = null;

		try {
			if (definizioneAllegatoId > 0) {
				allegato = definizioneAllegatoLocalService.getDefinizioneAllegato(definizioneAllegatoId);

				if (allegato.getFileEntryId() > 0) {
					FileEntry templateFileEntry = dlAppService.getFileEntry(allegato.getFileEntryId());

					if (Validator.isNotNull(templateFileEntry)) {
						modello = new DatiFileAllegato();
						modello.setFileName(templateFileEntry.getFileName());

						InputStream isTemplate = templateFileEntry.getContentStream();

						if (Validator.isNotNull(isTemplate)) {
							modello.setContenuto(isTemplate.readAllBytes());
						}
						else {
							log.error("AllegatoRichiestaService :: getModelloAllegato :: Input stream modello NULL!");
						}
					}
					else {
						log.error("AllegatoRichiestaService :: getModelloAllegato :: fileEntry dell'allegato con ID : " + definizioneAllegatoId + " NULL");
					}
				}
			}

		}
		catch (Exception e) {
			log.error("Errore durante il recupero dell'allegato con id definizione : " + definizioneAllegatoId + e.getMessage(), e);
		}

		return modello;
	}

	public void checkFirmaDigitaleDocumento(byte[] byteArray, String descrizione, String cfLoggato, List<TipoFirmaDigitale> tipiAmmessi, boolean sigilloQualificato, boolean verificaFirmaCf, long groupId, Contesto contesto) throws PDFSignatureException {
		VerificaFirmaOptions options = new VerificaFirmaOptions();
		options.setDescrizione(descrizione);
		options.setTipiFirmaAmmessi(tipiAmmessi.stream().map(Enum::name).collect(Collectors.toList()));
		options.setCfLoggato(cfLoggato);
		options.setVerificaSigilloQualificato(sigilloQualificato);
		options.setVerificaFirmaCf(verificaFirmaCf);

		try {
			firmaRemotaService.verificaFirma(groupId, contesto, byteArray, options);
		} catch (VerificaFirmaException e) {
			throw new PDFSignatureException(e.getMessage(), e);
		}
	}

	/**
	 *
	 * @param istanzaFormId
	 */
	public void deleteAllAllegati(long istanzaFormId) {
		List<AllegatoRichiesta> allegati = allegatoRichiestaLocalService.findByIstanzaFormId(istanzaFormId).stream().filter(x -> x.getDefinizioneAllegatoId() != 0).collect(Collectors.toList());

		FileService activeFileService = fileServiceFactory.getActiveFileService();

		for (AllegatoRichiesta ar : allegati) {
			activeFileService.deleteRequestFile(ar.getIdDocumentale(), ar.getGroupId());
			allegatoRichiestaLocalService.deleteAllegatoRichiesta(ar);
		}
	}

	/**
	 * Elimina gli {@link AllegatoRichiesta} ed i file corrispondenti dal sistema.
	 *
	 * @param allegatiRichiestaIds
	 */
	public void deleteAllegatiRichiesta(List<Long> allegatiRichiestaIds) {

		if (allegatiRichiestaIds != null) {
			FileService activeFileService = fileServiceFactory.getActiveFileService();
			for (Long allegatoRichiestaId : allegatiRichiestaIds) {
				if (!allegatoRichiestaId.equals(Long.valueOf(0))) {
					try {
						AllegatoRichiesta allegatoRichiesta = allegatoRichiestaLocalService.getAllegatoRichiesta(allegatoRichiestaId);
						activeFileService.deleteRequestFile(allegatoRichiesta.getIdDocumentale(), allegatoRichiesta.getGroupId());
						allegatoRichiestaLocalService.deleteAllegatoRichiesta(allegatoRichiesta);
					}
					catch (PortalException e) {
						log.error("deleteAllegatiRichiesta :: " + e.getMessage(), e);
					}
					catch (FileServiceException e) {
						log.error("deleteAllegatiRichiesta :: " + e.getMessage(), e);
					}
				}
			}
		}
	}

	public void deleteAllegato(long allegatoRichiestaId) {
		AllegatoRichiesta allegato = null;
		try {
			allegato = allegatoRichiestaLocalService.getAllegatoRichiesta(allegatoRichiestaId);
		} catch (PortalException e) {
			log.error("Allegato da eliminare non trovato :: " + e.getMessage(), e);
		}
		FileService activeFileService = fileServiceFactory.getActiveFileService();

		if (Validator.isNotNull(allegato)) {
			activeFileService.deleteRequestFile(allegato.getIdDocumentale(), allegato.getGroupId());
			allegatoRichiestaLocalService.deleteAllegatoRichiesta(allegato);
		}
	}
}

